/* The frame artwork.
 *
 * Each frame is a fixed 420x420 box with the QR window centred in it, sitting
 * on a 440x440 background card. Three frames per shape: a thin ring, a double
 * ring, and an organic wavy edge. All are pure geometry - koloqr.com also has
 * frames that carry a "SCAN ME" label, and those are left out on purpose,
 * because typesetting text on a curve needs a font parser and 200 KB of font
 * files that nothing else here would use.
 */
import { mk } from './svg.js';

var DESIGN_BOX = 420;
var DESIGN_QR  = 300;
var DESIGN_OFF = (DESIGN_BOX - DESIGN_QR) / 2;  // 60

// The artwork (frame + QR) is a 420×420 box, but it sits centered inside a
// slightly larger background "card" so there's a clean margin of bg color
// around the frame. CARD_BOX is the outer SVG size; CARD_PAD = the per-side
// gap ((440-420)/2 = 10). Each shape has its own background path authored at
// CARD_BOX×CARD_BOX (in Figma) - currently the square card is wired up.
var CARD_BOX = 440;
var CARD_PAD = (CARD_BOX - DESIGN_BOX) / 2;     // 10
// Background "card" geometry per shape (Figma exports, 440×440). Square and
// circle are rounded rects (just a corner radius); hex/triangle are outlines.
var SQUARE_BG_RX   = 76;                  // square card corner radius
var HEX_BG_PATH    = 'M284.125 18C316.279 18.0001 345.99 35.1541 362.067 63L426.443 174.501L427.185 175.811C442.273 202.979 442.273 236.023 427.185 263.191L426.443 264.501L362.067 376.002C345.99 403.848 316.279 421.002 284.125 421.002H155.376C123.222 421.002 93.5106 403.848 77.4336 376.002L13.0576 264.501C-3.0192 236.655 -3.01921 202.347 13.0576 174.501L77.4336 63C93.5106 35.154 123.222 18 155.376 18H284.125Z';
var TRI_BG_PATH    = 'M155.32 45.5703C184.583 -3.19032 255.415 -3.18986 284.679 45.5703L285.367 46.7402L427.846 293.519C456.898 343.84 420.583 406.741 362.478 406.741H77.5208C19.4161 406.741 -16.8995 343.84 12.1526 293.519L154.631 46.7402L155.32 45.5703Z';

// Prepend the background card for `shape` (filled with bg) to `svg`. Skipped
// for transparent bg. Square/circle use a rounded rect; hex/triangle a path.
function appendBgCard(svg, shape, bg) {
  if (!bg || bg === 'transparent') return;
  var el;
  if (shape === 'circular' || shape === 'square') {
    el = mk('rect');
    el.setAttribute('x', 2); el.setAttribute('y', 2);
    el.setAttribute('width', CARD_BOX - 4); el.setAttribute('height', CARD_BOX - 4);
    el.setAttribute('rx', shape === 'circular' ? (CARD_BOX - 4) / 2 : SQUARE_BG_RX);
  } else {
    el = mk('path');
    el.setAttribute('d', shape === 'hexagonal' ? HEX_BG_PATH : TRI_BG_PATH);
  }
    el.setAttribute('id', 'Background');
el.setAttribute('fill', bg);
  svg.appendChild(el);
}

// Each frame = an ordered list of <path> specs (each becomes its own object in

// Frameless specs - reuse renderDesignedFrame's content-placement math so a
// no-frame triangle/hexagon lands in the same 440×440 box, at the same size and
// position as its framed counterpart (only the ring/labels are omitted). This
// keeps the preview from "jumping" in scale when the frame is toggled off.
// The geometry mirrors every tri*/hex* frame (triTarget / innerW,innerH,cy).
var FRAMELESS_SPECS = {
  '__frameless_tri': { shape: 'triangular', content: 'tri', triTarget: { h: 329.5, cx: 210, cy: 236.8 } },
  '__frameless_hex': { shape: 'hexagonal',  content: 'hex', innerW: 322, innerH: 287, cy: 210.5 }
};

